import{z as o,x as n,o as e,c as p,q as r,j as i,D as E,d as B,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"偏见与毒性基准","description":"","frontmatter":{"title":"偏见与毒性基准","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/bias-toxicity-benchmarks.md","filePath":"llm/bias-toxicity-benchmarks.md","lastUpdated":1791413859000}'),d={name:"llm/bias-toxicity-benchmarks.md"};function m(h,a,D,c,P,F){const A=n("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="偏见与毒性基准" tabindex="-1">偏见与毒性基准 <a class="header-anchor" href="#偏见与毒性基准" aria-label="Permalink to &quot;偏见与毒性基准&quot;">​</a></h1><div class="epigraph"><p>毒性分数测的是分类器眼中的冒犯密度；偏见基准测的是刻板关联。两者都不是公平的完整定义，更不是红队的替代。</p><footer>—— Gehman 等 RealToxicityPrompts；Parrish 等 BBQ；Dhamala 等 BOLD</footer></div><p><a href="/llm/red-team-eval">上一课</a>覆盖对抗性突破。分布性伤害需要另一套仪器：在固定提示集上测刻板续写、毒性与 QA 偏见。本课写这些基准怎么读。缺口是不要用 Perspective 式分数签发「已对齐」。后课能力引出回到上限；本课先钉住平均行为。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Gehman 的 RealToxicityPrompts 用有毒前缀测续写毒性，依赖外部毒性分类器，分类器自身有偏见与域偏移。BOLD、CrowS-Pairs、StereoSet 测关联与填空偏好，题面英语中心、模板脆弱。Parrish 的 BBQ 把偏见做成有上下文与无上下文的 QA，能区分「不知道」与「靠刻板猜」。选错仪器会把拒答一切敏感话题当成偏见胜利。</p><p><span class="marginnote">术语翻译：毒性分类器是另一个现成的小模型，输入一段文字，输出「这段话有多冒犯」的 0 到 1 分。这些基准并不直接判定对错，而是拿这个裁判的分数当尺子——裁判自己的偏见会顺着尺子传进测量结果。</span></p><p>这些基准公开已久，易污染，也易被「对这套模板过拒」刷高。它们适合回归与切片诊断（按群体、按题型），不适合当唯一公平声明。</p><p><span class="marginnote">毒性分类器把身份词当风险特征时，关于受歧视群体的正当讨论会被标毒。必须人工抽检假阳性，不能把分类器均值写进模型卡当无害证明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分列：毒性续写（分类器 + 人抽检）、刻板 QA（BBQ 一类）、职业/性别关联、拒答切片。固定解码温度。报告按群体切片，禁止只报总均值——均值会让受害切片与过拒切片对冲。与产品语言一致：中文产品要有中文毒性与偏见样本，不能只跑英文 RealToxicityPrompts。</p><p><span class="marginnote">为什么重要：只报总均值时，A 群体上的高毒性可以被 B 群体上的零分对冲掉，平均数照样好看。按群体、按题型切片再报，就像体检报告分项列指标——「平均健康」掩盖不了单项异常。</span></p>',11)),(e(),i(s,null,{default:E(()=>[l(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E5%9B%BA%E5%AE%9A%E6%8F%90%E7%A4%BA%E9%9B%86%22%5D%20--%3E%20TOX%5B%22%E6%AF%92%E6%80%A7%E5%88%86%E7%B1%BB%E5%99%A8%22%5D%0A%20%20PR%20--%3E%20ST%5B%22%E5%88%BB%E6%9D%BF%20QA%20%2F%20%E5%A1%AB%E7%A9%BA%22%5D%0A%20%20TOX%20--%3E%20SLICE%5B%22%E7%BE%A4%E4%BD%93%E5%88%87%E7%89%87%22%5D%0A%20%20ST%20--%3E%20SLICE%0A%20%20SLICE%20--%3E%20HUM%5B%22%E4%BA%BA%E6%8A%BD%E6%A3%80%E5%81%87%E9%98%B3%E6%80%A7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[B("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"语言模型复制语料里的共现。基准把共现写成可计数的选择或续写。降低分数的路径有三条：改数据、改对齐拒答、改解码。前两条改模型，后一条改评测时的表面。只在评测时加过滤，卡上的数会好看、产品关掉过滤就回去。必须声明评测是否含过滤器。",-1)),(e(),i(s,null,{default:E(()=>[l(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%AF%92%E6%80%A7%20%2F%20%E5%81%8F%E8%A7%81%E5%88%86%E6%95%B0%E5%81%8F%E9%AB%98%22%5D%20--%3E%20P1%5B%22%E8%B7%AF%E4%B8%80%EF%BC%9A%E6%B8%85%E6%B4%97%E8%AF%AD%E6%96%99%E5%85%B1%E7%8E%B0%22%5D%0A%20%20S%20--%3E%20P2%5B%22%E8%B7%AF%E4%BA%8C%EF%BC%9A%E5%AF%B9%E9%BD%90%E9%98%B6%E6%AE%B5%E5%AD%A6%E6%8B%92%E7%AD%94%22%5D%0A%20%20S%20--%3E%20P3%5B%22%E8%B7%AF%E4%B8%89%EF%BC%9A%E8%AF%84%E6%B5%8B%E6%97%B6%E5%8A%A0%E8%BE%93%E5%87%BA%E8%BF%87%E6%BB%A4%22%5D%0A%20%20P1%20--%3E%20REAL%5B%22%E6%A8%A1%E5%9E%8B%E6%9C%AC%E8%BA%AB%E5%8F%98%E4%BA%86%22%5D%0A%20%20P2%20--%3E%20REAL%0A%20%20P3%20--%3E%20FACE%5B%22%E5%8D%B7%E9%9D%A2%E5%A5%BD%E7%9C%8B%EF%BC%8C%E5%85%B3%E6%8E%89%E8%BF%87%E6%BB%A4%E5%B0%B1%E5%9B%9E%E5%BC%B9%22%5D%0A%20%20REAL%20--%3E%20CARD%5B%22%E5%8F%AF%E5%86%99%E8%BF%9B%E6%A8%A1%E5%9E%8B%E5%8D%A1%E7%9A%84%E8%83%BD%E5%8A%9B%22%5D%0A%20%20FACE%20--%3E%20DECL%5B%22%E5%BF%85%E9%A1%BB%E5%A3%B0%E6%98%8E%E5%90%AB%E8%BF%87%E6%BB%A4%E5%99%A8%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>这张图回答的问题是：同样是「分数降了」，三条路的性质完全不同——前两条改变模型分布，第三条只是把问题挡在评测员的视野外。</p><p><span class="marginnote">直觉类比：只在评测时开输出过滤，相当于交卷后偷偷用涂改液把错题盖住再交给老师——卷面干净了，考生本人一点没变；产品一旦关掉过滤，原始行为原样回来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基准不覆盖交叉身份、也不覆盖部署语境下的权力关系。法律合规另走审计。下一课能力引出：对危险与偏见任务，默认提示可能低估模型实际上限。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>毒性与偏见基准是分布回归，按切片读，不单报均值。</li><li>分类器假阳性要人抽检；过拒不是公平。</li><li>评测是否含过滤器必须声明。</li><li>出处：Gehman 等 RealToxicityPrompts；Dhamala 等 BOLD；CrowS-Pairs / StereoSet。</li></ul>',6))])}const T=o(d,[["render",m]]);export{C as __pageData,T as default};
